            return {}
        raise
    return {tuple(json.loads(r[0])): (r[1], r[2]) for r in rows}


def _patch_sort_key(triple: list) -> tuple:
    # Identity, then record number, then logical field in FIELDS order (the
    # audit field order); fields are limited to FIELDS so the index is total.
    return triple[0], FIELDS.index(triple[1])


def _load_csv_header(data: bytes, input_name: str) -> tuple[str, list[str]]:
    try:
        text = data.decode("utf-8-sig")
    except UnicodeDecodeError as exc:
        raise AuditError(
            f"input is not valid UTF-8: {exc.reason} at byte {exc.start}",
            filename=input_name,
        )
    reader = csv.reader(io.StringIO(text, newline=""), strict=True)
    try:
        header = next(reader)
    except StopIteration:
        raise AuditError("CSV is empty (no header)", filename=input_name)
    except csv.Error as exc:
        raise AuditError(f"malformed CSV: {exc}", filename=input_name)
    if not header or any(name == "" for name in header) or len(set(header)) != len(header):
        raise AuditError("malformed CSV header", filename=input_name)
    return text, header


def _apply_patches(
    text: str,
    header: list[str],
    columns: dict[str, int],
    changes: dict[tuple[int, str], str],
    input_name: str,
) -> tuple[str, set[int]]:
    """Return the corrected CSV text and the record numbers touched.

    Every change must address an existing, well-formed data record; the
    corrected CSV keeps the same header, column order, extra columns and
    every untouched cell byte for byte (apart from the rewritten cells).
    """
    reader = csv.reader(io.StringIO(text, newline=""), strict=True)
    try:
        next(reader)  # header, already validated
    except csv.Error as exc:  # pragma: no cover - header parsed above
        raise AuditError(f"malformed CSV: {exc}", filename=input_name)

    out = io.StringIO(newline="")
    writer = csv.writer(out, lineterminator="\n")
    writer.writerow(header)

    record_no = 1
    changed_records: set[int] = set()
    remaining = dict(changes)
    while True:
        try:
            raw = next(reader)
        except StopIteration:
            break
        except csv.Error as exc:
            raise AuditError(f"malformed CSV near record {record_no + 1}: {exc}",
                             filename=input_name)
        record_no += 1
        if not raw or (len(raw) == 1 and raw[0].strip() == ""):
            # Blank records are skipped by the audit and carry no record
            # content; reproduce a single empty line so row numbering and
            # the physical file stay aligned with the input.
            writer.writerow([])
            continue
        if len(raw) != len(header):
            raise AuditError(
                f"record {record_no} has {len(raw)} fields but the header has "
                f"{len(header)}",
                filename=input_name,
            )
        row = list(raw)
        for field in FIELDS:
            new_value = remaining.pop((record_no, field), None)
            if new_value is not None:
                row[columns[field]] = new_value
                changed_records.add(record_no)
        writer.writerow(row)

    if remaining:
        target = next(iter(remaining))
        raise AuditError(
            f"patch target record {target[0]} does not exist in the input",
            filename="PATCH",
        )
    return out.getvalue(), changed_records


def _build_snapshot(
    decisions: dict[tuple, tuple[str, str, str]],
    proposals: dict[tuple, tuple[str, str]],
) -> list:
    """Canonical, identity-sorted snapshot of decisions and proposals.

    Only ``fix`` decisions carrying a proposal are part of the apply set,
    but the full set of fix decisions is snapshotted for traceability.
    """
    snapshot = []
    for ident in sorted(decisions):
        identity_json, reason, finding_json = decisions[ident]
        entry = {
            "identity": list(ident),
            "reason": reason,
            "finding": json.loads(finding_json),
        }
        proposal = proposals.get(ident)
        if proposal is not None:
            entry["proposal"] = {
                "finding": json.loads(proposal[0]),
                "patch": json.loads(proposal[1]),
            }
        snapshot.append(entry)
    return snapshot


def run_apply_fixes(
    db_path: str,
    source_id: str,
    derived_id: str,
    input_path: str,
    output_path: str,
    report_path: str | None = None,
    stdout: BinaryIO | TextIO | None = None,
) -> int:
    """Apply traced fixes, re-audit, and store a derived batch; exit code.

    INPUT's SHA-256 must equal the source batch hash.  Every ``fix``
    decision of the source batch must have a proposal whose stored finding
    still matches.  Proposals are applied ordered by identity, record
    number and field, then the corrected CSV is re-audited with the source
    schema.  The audit JSONL goes to stdout or ``--report R``; the corrected
    CSV is atomically written to ``--output``.  A derived batch tracing the
    new hash, schema, findings, source and decision/proposal snapshots is
    stored in one transaction with the file writes.  Repeating the same
    derived id with the same content is idempotent (exit 0); different
    content raises :class:`FixConflictError` (exit 3).  Any stale decision,
    illegal patch, I/O, database or audit error raises :class:`AuditError`
    (exit 2); the database, the derived batch and any old output are left
    untouched and temporary files are cleaned up.
    """
    try:
        with open(input_path, "rb") as fh:
            data = fh.read()
    except OSError as exc:
        raise AuditError(f"cannot read input file: {exc}", filename=input_path)

    source = fetch_batch(db_path, source_id)
    if source is None:
        raise AuditError(f"batch {source_id!r} not found", filename=db_path)
    source_hash, source_schema_json, source_findings_json = source
    if hashlib.sha256(data).hexdigest() != source_hash:
        raise AuditError(
            f"INPUT hash does not match source batch {source_id!r}",
            filename=input_path,
        )

    schema = parse_schema(json.dumps(json.loads(source_schema_json)))
    text, header = _load_csv_header(data, input_path)
    columns = resolve_columns(schema, header)
    source_findings = json.loads(source_findings_json)

    # Everything below that touches the database is one transaction, and
    # the file writes participate in it: a failed write rolls the derived
    # batch back, exactly like audit-orders --db/--batch.
    with _fix_transaction(db_path) as conn:
        decisions = _fetch_fix_decisions(conn, source_id)
        proposals = _fetch_proposals(conn, source_id)

        # Identity ordering first; within one finding, patches sort by
        # record number then logical field.
        ordered_changes: dict[tuple[int, str], str] = {}
        for ident in sorted(proposals):
            if ident not in decisions:
                # A proposal without a current fix decision is stale.
                raise AuditError(
                    f"stored proposal for identity {list(ident)} has no fix "
                    f"decision in batch {source_id!r}",
                    filename=db_path,
                )
            finding_json, patch_json = proposals[ident]
            finding = json.loads(finding_json)
            matches = [f for f in source_findings
                       if tuple(finding_identity(f)) == ident]
            if not matches or _canonical_json(matches[0]) != finding_json:
                raise AuditError(
                    f"proposal for identity {list(ident)} no longer matches a "
                    f"finding of batch {source_id!r}",
                    filename=db_path,
                )
            patch = json.loads(patch_json)
            _validate_patch_against_finding(patch, ident, finding)
            for recno, field, new_value in sorted(patch, key=_patch_sort_key):
                key = (recno, field)
                if key in ordered_changes:
                    raise AuditError(
                        f"proposals target cell ({recno}, {field!r}) more than "
                        "once across findings",
                        filename="PATCH",
                    )
                ordered_changes[key] = new_value

        # Every fix decision must have a proposal.
        missing = sorted(set(decisions) - set(proposals))
        if missing:
            raise AuditError(
                f"fix decision for identity {list(missing[0])} in batch "
                f"{source_id!r} has no proposal",
                filename=db_path,
            )

        corrected_text, _changed = _apply_patches(
            text, header, columns, ordered_changes, input_path
        )
        corrected_bytes = corrected_text.encode("utf-8")

        findings, _ = audit(corrected_bytes, json.dumps(schema), output_path)
        payload = serialize(findings)

        snapshot = _build_snapshot(decisions, proposals)
        derived_record = (
            hashlib.sha256(corrected_bytes).hexdigest(),
            _canonical_json(schema),
            _canonical_json(findings[:-1]),
            source_id,
            _canonical_json(snapshot),
            _canonical_json([json.loads(p[1]) for p in (
                proposals[i] for i in sorted(proposals)
            )]),
        )

        existing = conn.execute(
            "SELECT input_sha256, schema_json, findings_json, source_batch_id, "
            "decisions_json, proposals_json FROM derived_batches "
            "WHERE derived_id = ?",
            (derived_id,),
        ).fetchone()
        if existing is not None:
            if tuple(existing) != derived_record:
                raise FixConflictError(
                    f"derived batch {derived_id!r} is already stored with "
                    "different content"
                )
        else:
            conn.execute(
                "INSERT INTO derived_batches "
                "(derived_id, input_sha256, schema_json, findings_json, "
                "source_batch_id, decisions_json, proposals_json) "
                "VALUES (?, ?, ?, ?, ?, ?, ?)",
                (derived_id, *derived_record),
            )

        # Outputs participate in the transaction; both use the atomic
        # replace that preserves old files and cleans temp files on error.
        emit_report(payload, report_path, stdout)
        _atomic_write(output_path, corrected_bytes)
    return 0

